<script setup>
import ItemDetails from './ItemDetails.vue';
import PurchaseOrderFields from './PurchaseOrderFields.vue';
import {computed,ref,reactive,watch,onBeforeUnmount,nextTick} from 'vue';
import {purchaseEditFields,normalizePurchaseEdit} from '../../../../web/purchase-edit.js';
const props=defineProps({module:Object,data:Object,saveRecord:Function,createRecord:Function});
const confirmingApproval=ref(false);
const exporting=ref(''),exportError=ref('');
async function exportPdf(row){if(exporting.value)return;exporting.value=row.id;exportError.value='';try{const {downloadPurchaseOrderPdf}=await import('../../../../web/purchase-order-pdf.js');await downloadPurchaseOrderPdf(row,props.data?.suppliers||[]);}catch(e){exportError.value=e.message||'No se pudo descargar el PDF.';}finally{exporting.value='';}}
const creating=ref(false),newId=ref(''),editing=ref(false),saving=ref(false),error=ref(''),success=ref(null),form=reactive({});
const search=ref(''),page=ref(1),size=ref(25),selected=ref(null),dialog=ref(null);
const fields={suppliers:[['identification','NIT'],['name','Nombre'],['phone1','Teléfono 1'],['phone2','Teléfono 2'],['email','Email'],['website','Sitio web'],['address','Dirección'],['city','Ciudad'],['certified','Certificado'],['creditType','Tipo de crédito'],['creditAmount','Monto de crédito'],['evaluation','Evaluación']],supplierContacts:[['name','Nombre'],['supplierName','Proveedor'],['position','Cargo'],['phone1','Teléfono 1'],['phone2','Teléfono 2'],['mobile','Celular'],['email','Email'],['comments','Comentarios']],items:[['code','Código'],['name','Nombre'],['unit','Unidad'],['category','Categoría'],['location','Ubicación'],['supplierName','Proveedor principal'],['secondSupplierName','Proveedor secundario'],['description','Descripción']],purchaseOrders:[['number','Número'],['supplierName','Proveedor'],['status','Estado'],['date','Creación'],['deliveryDate','Fecha esperada'],['approverName','Usuario que aprueba'],['total','Total'],['comments','Comentarios']],kardex:[['date','Fecha'],['itemName','Ítem'],['movement','Movimiento'],['entry','Entrada'],['exit','Salida'],['balance','Saldo'],['document','Documento'],['quantity','Cantidad solicitada'],['status','Estado'],['comments','Comentarios']]};
const supplierContacts=computed(()=>creating.value||!selected.value?.id?[]:(props.data?.supplierContacts||[]).filter(contact=>contact.supplierId===selected.value.id));
const contactColumns=[['name','Nombre'],['position','Cargo'],['phone1','Teléfono 1'],['phone2','Teléfono 2'],['mobile','Celular'],['email','Email'],['comments','Comentarios']];
const columns=computed(()=>fields[props.module.id]||[]);
const rows=computed(()=>{const needle=search.value.trim().toLocaleLowerCase('es');return (props.data?.[props.module.id]||[]).map(row=>props.module.id==='purchaseOrders'?{...row,approverName:row.approval?.approvedName||row.approval?.approvedEmail||row.approverName||''}:row).filter(r=>!needle||columns.value.some(([k])=>String(r[k]??'').toLocaleLowerCase('es').includes(needle))).slice().sort((a,b)=> (props.module.id==='purchaseOrders'?String(b.date||'').localeCompare(String(a.date||'')):0) || String(a.name||a.number||'').localeCompare(String(b.name||b.number||''),'es',{numeric:true}));});
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/size.value)));
const visible=computed(()=>rows.value.slice((page.value-1)*size.value,page.value*size.value));
const host=(()=>{try{return window.parent.location.origin===window.location.origin?window.parent.document.body:document.body;}catch{return document.body;}})();
function close(){if(saving.value)return;confirmingApproval.value=false;success.value?.close();dialog.value?.close();selected.value=null;creating.value=false;editing.value=false;error.value='';}
function orderForm(row={}){return {supplierId:row.supplierId||'',date:row.date||new Date().toLocaleDateString('en-CA',{timeZone:'America/Bogota'}),paymentDays:row.paymentDays??0,deliveryDate:row.deliveryDate||'',deliveryAddress:row.deliveryAddress||'',reference:row.reference||'',comments:row.comments||'',lines:(row.lines||[]).map(l=>({key:crypto.randomUUID(),productId:l.productId,description:l.description,code:l.code,quantity:String(l.quantityUnits/1000),price:String(l.unitPriceCents/100),rate:l.rate}))};}
function view(row,edit=false){confirmingApproval.value=false;creating.value=false;selected.value=row;editing.value=edit;error.value='';for(const key of Object.keys(purchaseEditFields[props.module.id]||{}))form[key]=String(row[key]??'');if(props.module.id==='purchaseOrders')Object.assign(form,orderForm(row));dialog.value.showModal();}
const singular={suppliers:'proveedor',supplierContacts:'contacto',items:'ítem',purchaseOrders:'borrador de orden',kardex:'movimiento pendiente'};
function startCreate(){creating.value=true;editing.value=true;error.value='';newId.value='new_'+crypto.randomUUID();selected.value={};for(const key of Object.keys(form))delete form[key];for(const key of Object.keys(purchaseEditFields[props.module.id]||{}))form[key]='';Object.assign(form,{supplierId:'',secondSupplierId:'',itemId:'',date:new Date().toLocaleDateString('en-CA',{timeZone:'America/Bogota'}),reference:'',movement:'ENTRY',quantity:1,...(props.module.id==='suppliers'?{creditAmount:'3000000'}:{})});if(props.module.id==='purchaseOrders')Object.assign(form,orderForm());dialog.value.showModal();}
function display(key,value){if(value==null||value==='')return '—';if(['date','deliveryDate'].includes(key)&&/^\d{4}-\d{2}-\d{2}$/.test(String(value)))return String(value).split('-').reverse().join('/');if(key==='total')return new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP'}).format(Number(value));if(key==='creditAmount')return new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',minimumFractionDigits:2}).format(Number(value));if(key==='evaluation')return new Intl.NumberFormat('es-CO',{maximumFractionDigits:2}).format(Number(value));return key==='status'?({CREATED:'Creada',DRAFT:'Borrador',APPROVED:'Aprobada',PENDING:'Pendiente de aplicar'}[value]||value||'—'):key==='movement'?({ENTRY:'Entrada',EXIT:'Salida'}[value]||value||'—'):value??'—';}
const editable=computed(()=>columns.value.filter(([key])=>key in (purchaseEditFields[props.module.id]||{})));
function inputValue(key,event){form[key]=props.module.id!=='suppliers'&&['phone1','phone2','mobile'].includes(key)?event.target.value.replace(/[^0-9]/g,''):event.target.value;event.target.value=form[key];}
async function save(){if(saving.value||!props.data?.canEdit)return;saving.value=true;error.value='';try{const values=creating.value||props.module.id==='purchaseOrders'?{...form}:normalizePurchaseEdit(props.module.id,form);selected.value=creating.value?await props.createRecord(props.module.id,newId.value,values):await props.saveRecord(props.module.id,selected.value,values);creating.value=false;editing.value=false;await nextTick();success.value?.showModal();}catch(e){error.value=e.code==='permission-denied'?'El guardado de Compras está pendiente de habilitación.':e.message||'No se pudo guardar.';}finally{saving.value=false;}}
async function approveSelected(){
 if(saving.value||!props.data?.canEdit||!props.data?.approvalAvailable)return;
 saving.value=true;error.value='';
 try{selected.value=await props.saveRecord('purchaseOrders',selected.value,{action:'approve'});confirmingApproval.value=false;await nextTick();success.value?.showModal();}
 catch(e){error.value=e.message||'No se pudo aprobar la orden.';}finally{saving.value=false;}
}
function accept(){success.value?.close();dialog.value?.querySelector('footer button')?.focus();}
watch(()=>props.module.id,()=>{search.value='';page.value=1;close();});watch(()=>props.data,()=>{if(!props.data||props.data.unavailable||props.data.loading)close();});watch([search,size],()=>{page.value=1;});onBeforeUnmount(()=>{success.value?.close();dialog.value?.close();});
</script>
<template>
<p v-if="data?.loading" role="status">Cargando datos…</p><p v-else-if="data?.error" role="alert">{{ data.error }}</p><p v-else-if="!data || data.unavailable">La importación de Compras corresponde a la compañía DyD.</p>
<template v-else>
<p v-if="exportError" role="alert">{{ exportError }}</p><div class="process-module-heading"><button v-if="data.canEdit" type="button" class="commercial-create-account" @click="startCreate">+ Crear {{ singular[module.id] }}</button></div><div class="commercial-filters"><label>Buscar<input v-model="search" type="search" :placeholder="'Buscar en '+module.label.toLocaleLowerCase('es')"></label><label>Por página<select v-model.number="size"><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option></select></label></div>
<div class="process-data-table-wrap"><table class="process-data-table purchase-records-table" :aria-label="module.label"><thead><tr><th v-for="[key,label] in columns" :key="key" scope="col">{{ label }}</th><th scope="col">Acciones</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td v-for="[key] in columns" :key="key">{{ display(key,row[key]) }}</td><td><button type="button" class="commercial-view-account" title="Ver información" aria-label="Ver información" @click="view(row)"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button><button v-if="module.id==='purchaseOrders'" type="button" class="commercial-view-account" :disabled="!!exporting" :title="exporting===row.id?'Generando PDF…':'Exportar a PDF'" aria-label="Exportar orden de compra a PDF" @click="exportPdf(row)"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M12 11v7m-3-3 3 3 3-3"/></svg></button></td></tr><tr v-if="!visible.length"><td :colspan="columns.length+1">{{ search?'No se encontraron resultados.':['purchaseOrders','kardex'].includes(module.id)?'No se encontraron operaciones de 2026 en la copia importada.':'No hay registros importados.' }}</td></tr></tbody></table></div>
<div class="commercial-pagination"><span>{{ rows.length }} registros · Página {{ page }} de {{ pages }}</span><button type="button" :disabled="page<=1" @click="page--">Anterior</button><button type="button" :disabled="page>=pages" @click="page++">Siguiente</button></div>
</template>
<Teleport :to="host"><link rel="stylesheet" href="/procesos/account-detail.css"><dialog ref="dialog" class="sigmyp-account-dialog sigmyp-editable-account-dialog sigmyp-purchase-dialog" :class="{'sigmyp-supplier-dialog':module.id==='suppliers','sigmyp-order-dialog':module.id==='purchaseOrders','sigmyp-item-dialog':module.id==='items'}" aria-labelledby="purchase-detail-title" @cancel.prevent="close"><header class="sigmyp-account-header"><h2 id="purchase-detail-title">{{ creating?'Crear '+singular[module.id]:selected?.name || module.label }}</h2><button type="button" class="sigmyp-account-close" @click="close" :disabled="saving" autofocus>Cerrar ✕</button></header><div class="sigmyp-contact-content sigmyp-record-scroll" :class="{'supplier-detail-layout':module.id==='suppliers'}"><section class="purchase-detail-profile"><h3 v-if="module.id==='suppliers'">Proveedor</h3><form v-if="selected && editing" id="purchase-edit-form" class="sigmyp-account-form" @submit.prevent="save"><fieldset :disabled="saving"><PurchaseOrderFields v-if="module.id==='purchaseOrders'" :form="form" :items="data.items" :suppliers="data.suppliers" :record="selected" :creating="creating" editing /><template v-else>
<label v-if="module.id==='supplierContacts' || (creating && module.id==='items')">Proveedor<select v-model="form.supplierId" :required="module.id!=='items'"><option value="">Selecciona un proveedor</option><option v-for="supplier in data.suppliers" :key="supplier.id" :value="supplier.id">{{ supplier.name }}</option></select></label>
<template v-if="creating"><p v-if="module.id==='purchaseOrders'">Se creará un borrador de cabecera. Los ítems e importes se incorporarán al completar el flujo de órdenes de compra.</p><p v-if="module.id==='kardex'">Este movimiento quedará pendiente y no modificará existencias ni saldos.</p>
<label v-if="module.id==='items'">Proveedor secundario<select v-model="form.secondSupplierId"><option value="">Sin proveedor secundario</option><option v-for="supplier in data.suppliers" :key="supplier.id" :value="supplier.id">{{ supplier.name }}</option></select></label>
<label v-if="['purchaseOrders','kardex'].includes(module.id)">Fecha<input type="date" v-model="form.date" min="2026-01-01" max="2026-12-31" required></label>
<label v-if="module.id==='purchaseOrders'">Referencia<input v-model="form.reference" maxlength="200"></label>
<template v-if="module.id==='kardex'"><label>Ítem<select v-model="form.itemId" required><option value="">Selecciona un ítem</option><option v-for="item in data.items" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }}</option></select></label><label>Movimiento<select v-model="form.movement"><option value="ENTRY">Entrada</option><option value="EXIT">Salida</option></select></label><label>Cantidad solicitada<input v-model="form.quantity" type="number" min="0.001" max="1000000000" step="0.001" required></label></template>
</template><p v-if="!creating && module.id==='items'">Proveedor principal: {{ selected.supplierName||'Sin asignar' }} · Proveedor secundario: {{ selected.secondSupplierName||'Sin asignar' }}</p><p v-if="!creating && module.id==='kardex'">Puedes corregir las observaciones. Las cantidades y los saldos del movimiento se conservan.</p><p v-if="!creating && module.id==='purchaseOrders'">Puedes corregir las condiciones y observaciones. El estado, los productos y los importes se conservan.</p><label v-for="[key,label] in editable" :key="key">{{ label }}<textarea v-if="['description','comments','paymentMethod'].includes(key)" v-model="form[key]" rows="4" :maxlength="purchaseEditFields[module.id][key]"></textarea><input v-else :value="form[key]" @input="inputValue(key,$event)" :type="key==='creditAmount'?'number':key==='email'?'email':['phone1','phone2','mobile'].includes(key)?'tel':'text'" :inputmode="['phone1','phone2','mobile'].includes(key)?'numeric':undefined" :min="key==='creditAmount'?0:undefined" :step="key==='creditAmount'?'0.01':undefined" :required="key==='name'" :maxlength="purchaseEditFields[module.id][key]"></label><label v-if="module.id==='suppliers'">Evaluación<input :value="creating?'1':display('evaluation',selected.evaluation)" readonly aria-readonly="true"></label></template></fieldset></form><PurchaseOrderFields v-else-if="selected && module.id==='purchaseOrders'" :form="form" :items="data.items" :suppliers="data.suppliers" :record="selected" /><ItemDetails v-else-if="selected && module.id==='items'" :record="selected" :data="data" /><dl v-else-if="selected"><div v-for="[key,label] in columns" :key="key" style="margin-bottom:16px"><dt><strong>{{ label }}</strong></dt><dd style="margin:4px 0;white-space:pre-wrap;overflow-wrap:anywhere">{{ display(key,selected[key]) }}</dd></div></dl><p v-if="error" role="alert" class="sigmyp-account-save-status">{{ error }}</p></section>
<section v-if="module.id==='suppliers'" class="supplier-related-contacts" aria-labelledby="supplier-contacts-title"><h3 id="supplier-contacts-title">Contactos <span>{{ supplierContacts.length }}</span></h3><div class="sigmyp-account-table-scroll"><table aria-label="Contactos del proveedor"><thead><tr><th v-for="[key,label] in contactColumns" :key="key" scope="col">{{ label }}</th></tr></thead><tbody><tr v-for="contact in supplierContacts" :key="contact.id"><td v-for="[key] in contactColumns" :key="key">{{ contact[key] || '—' }}</td></tr><tr v-if="!supplierContacts.length"><td :colspan="contactColumns.length">{{ creating?'Después de guardar el proveedor, puedes asociar contactos desde la pestaña Contactos.':'Este proveedor no tiene contactos asociados.' }}</td></tr></tbody></table></div></section>
</div><div v-if="confirmingApproval" class="purchase-approval-confirm"><p>¿Aprobar esta orden por {{ display('total',selected.total) }}? Sus datos e ítems quedarán bloqueados para edición.</p><button type="button" :disabled="saving" @click="approveSelected">{{ saving?'Aprobando…':'Confirmar aprobación' }}</button><button type="button" :disabled="saving" @click="confirmingApproval=false">Cancelar</button></div><footer class="sigmyp-account-footer"><button v-if="module.id==='purchaseOrders' && !editing && selected?.status==='DRAFT' && selected?.orderVersion && data?.canEdit" type="button" :disabled="saving || !data.approvalAvailable" :title="data.approvalAvailable?'Aprobar esta orden':'La aprobación todavía no está habilitada.'" @click="confirmingApproval=true">Aprobar orden</button><button v-if="editing" type="submit" form="purchase-edit-form" :disabled="saving">{{ saving?'Guardando…':creating?'Crear':'Guardar cambios' }}</button><button v-else-if="data?.canEdit && (module.id!=='purchaseOrders' || selected?.status==='DRAFT')" type="button" @click="view(selected,true)">Actualizar datos</button><button type="button" class="sigmyp-account-close" :disabled="saving" @click="close">Cerrar</button></footer></dialog><dialog ref="success" class="sigmyp-account-success" role="alertdialog" aria-labelledby="purchase-success-title" aria-describedby="purchase-success-text" @cancel.prevent="accept"><span class="sigmyp-account-success-icon" aria-hidden="true">✓</span><h2 id="purchase-success-title">Guardado exitoso</h2><p id="purchase-success-text">Los datos se guardaron correctamente.</p><button type="button" @click="accept" autofocus>Aceptar</button></dialog></Teleport>
</template>
